+import { Type } from 'class-transformer';
+import {
+    IsArray,
+    IsNumberString,
+    IsOptional,
+    IsString,
+    MinLength,
+    Validate,
+    ValidateNested,
+    ValidatorConstraint,
+    ValidatorConstraintInterface,
+    ValidationArguments,
+} from 'class-validator';
+import { ApiProperty } from '@nestjs/swagger';
+
+export class UsageTier {
+    @IsNumberString()
+    @ApiProperty({ example: '1' })
+    tierPosition: string;
+
+    @IsString()
+    @MinLength(1)
+    @ApiProperty({ examples: ['1000', 'inf'] })
+    upperBound: string;
+
+    @IsString()
+    @IsOptional()
+    @ApiProperty({ required: false, example: 'Growth' })
+    tierName?: string;
+
+    @IsNumberString()
+    @IsOptional()
+    @ApiProperty({ required: false, example: '0.04' })
+    unitPrice?: string;
+}
+
+export function validateUsageTiers(tiers: UsageTier[], usageIncrement: string): string | undefined {
+    if (!Array.isArray(tiers) || tiers.length === 0) {
+        return 'tiers must contain at least one tier';
+    }
+
+    const increment = Number(usageIncrement);
+    if (!Number.isInteger(increment) || increment <= 0) {
+        return 'usageIncrement must be a positive integer';
+    }
+
+    const sortedTiers = [...tiers].sort((left, right) => Number(left.tierPosition) - Number(right.tierPosition));
+    const positions = new Set<string>();
+    let previousBound = 0;
+
+    for (let index = 0; index < sortedTiers.length; index += 1) {
+        const tier = sortedTiers[index];
+        if (!/^\d+$/.test(tier?.tierPosition) || positions.has(tier.tierPosition)) {
+            return 'tierPosition must be a unique non-negative integer string';
+        }
+        positions.add(tier.tierPosition);
+
+        if (index > 0 && tier.unitPrice === undefined) {
+            return 'Every tier after the first must include unitPrice';
+        }
+        if (tier.unitPrice !== undefined && (!/^\d+(\.\d+)?$/.test(tier.unitPrice) || Number(tier.unitPrice) < 0)) {
+            return 'unitPrice must be a non-negative numeric string';
+        }
+
+        if (tier.upperBound === 'inf') {
+            if (index !== sortedTiers.length - 1) {
+                return 'upperBound "inf" is only allowed on the final tier';
+            }
+            continue;
+        }
+
+        if (!/^\d+(\.\d+)?$/.test(tier.upperBound)) {
+            return 'upperBound must be a numeric string or "inf"';
+        }
+        const upperBound = Number(tier.upperBound);
+        if (!Number.isFinite(upperBound) || upperBound <= previousBound) {
+            return 'Tier upper bounds must increase without overlap';
+        }
+        if (!Number.isInteger(upperBound / increment)) {
+            return 'Tier upper bounds must align to usageIncrement';
+        }
+        previousBound = upperBound;
+    }
+}
+
+@ValidatorConstraint({ name: 'UsageTiers', async: false })
+export class UsageTiersRule implements ValidatorConstraintInterface {
+    validate(tiers: UsageTier[] | null, args: ValidationArguments) {
+        if (tiers === null || tiers === undefined) return true;
+        const usageIncrement = (args.object as { usageIncrement?: string }).usageIncrement;
+        if (usageIncrement === undefined) return Array.isArray(tiers) && tiers.length > 0;
+        return validateUsageTiers(tiers, usageIncrement) === undefined;
+    }
+
+    defaultMessage(args: ValidationArguments) {
+        const tiers = args.value as UsageTier[];
+        const usageIncrement = (args.object as { usageIncrement?: string }).usageIncrement;
+        return usageIncrement === undefined
+            ? 'tiers must contain at least one tier'
+            : validateUsageTiers(tiers, usageIncrement) || 'Invalid tiers';
+    }
+}
+
+export class UsageTiersContainer {
+    @IsArray()
+    @ValidateNested({ each: true })
+    @Type(() => UsageTier)
+    @Validate(UsageTiersRule)
+    tiers: UsageTier[];
+}
